struct BorrowedData<'a> {
    name: &'a str,
    description: &'a str,
}

impl<'a> Clone for BorrowedData<'a> {
    fn clone(&self) -> Self {
        BorrowedData {
            name: self.name,
            description: self.description,
        }
    }
}

fn main() {
    let data = BorrowedData {
        name: "Alice",
        description: "A developer",
    };

    let cloned = data.clone();
    assert_eq!(cloned.name, "Alice");
    assert_eq!(cloned.description, "A developer");

    let original = BorrowedData {
        name: "Bob",
        description: "A manager",
    };

    let moved = original;
    assert_eq!(moved.name, "Bob");
    assert_eq!(moved.description, "A manager");

    println!("success");
}
